script:
document.addEventListener("DOMContentLoaded", async () => {
  // Setup Search & Tags
  const urlParams = new URLSearchParams(window.location.search);
  const searchQuery = urlParams.get("search");
  const tagQuery = urlParams.get("tag");

  const searchInput = document.querySelector(".search-input");
  searchInput?.focus();
  searchInput?.select();

  const tagsContainer = document.querySelector(".tags-container");
  const tagItems = document.querySelectorAll(".tag-item");

  if (tagItems) {
    tagItems.forEach((item) => {
      const xBtn = item.nextElementSibling;
      const textBlock = item.querySelector(".__text_block__");
      const tagText = textBlock
        ? textBlock.innerText.trim()
        : item.innerText.trim();

      const isXBtn = xBtn && xBtn.classList.contains("tag-x-btn");

      if (tagQuery && tagQuery === tagText) {
        item.style.backgroundColor = "var(--ink-gray-2)";
        if (textBlock) textBlock.style.color = "var(--ink-gray-7)";
        item.style.color = "var(--ink-gray-7)";

        if (isXBtn) {
          xBtn.style.display = "";
          item.appendChild(xBtn);
          item.style.display = "flex";
          item.style.alignItems = "center";
          item.style.gap = "8px";
        }

        if (tagsContainer) {
          tagsContainer.prepend(item);
        }
      } else {
        item.style.backgroundColor = "";
        if (textBlock) textBlock.style.color = "";
        item.style.color = "";
        if (isXBtn) xBtn.style.display = "none";
      }

      item.addEventListener("click", () => {
        if (tagQuery === tagText) return;
        const params = new URLSearchParams(window.location.search);
        params.set("tag", tagText);
        params.delete("page");
        window.location.search = params.toString();
      });

      if (isXBtn) {
        xBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          const params = new URLSearchParams(window.location.search);
          params.delete("tag");
          params.delete("page");
          window.location.search = params.toString();
        });
      }
    });

    const updateTagsScrollFade = () => {
      const { scrollLeft, scrollWidth, clientWidth } = tagsContainer;
      if (scrollWidth <= clientWidth) {
        tagsContainer.style.maskImage = "none";
        tagsContainer.style.webkitMaskImage = "none";
        return;
      }

      const atStart = scrollLeft <= 0;
      const atEnd = Math.ceil(scrollLeft + clientWidth) >= scrollWidth - 1;

      let mask = "none";
      if (atStart && !atEnd) {
        mask =
          "linear-gradient(to right, black, black calc(100% - 50px), transparent)";
      } else if (!atStart && atEnd) {
        mask = "linear-gradient(to right, transparent, black 50px, black)";
      } else if (!atStart && !atEnd) {
        mask =
          "linear-gradient(to right, transparent, black 50px, black calc(100% - 50px), transparent)";
      }

      tagsContainer.style.maskImage = mask;
      tagsContainer.style.webkitMaskImage = mask;
    };

    tagsContainer.addEventListener("scroll", updateTagsScrollFade, {
      passive: true,
    });
    window.addEventListener("resize", updateTagsScrollFade);
    setTimeout(updateTagsScrollFade, 100);
  }

  if (searchInput && searchQuery) {
    searchInput.value = searchQuery;
  }

  if (searchInput) {
    searchInput.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        const params = new URLSearchParams(window.location.search);
        if (e.target.value) {
          params.set("search", e.target.value);
        } else {
          params.delete("search");
        }
        params.delete("page"); // reset page on search
        window.location.search = params.toString();
      }
    });
  }

  // Setup Pagination
  const currentPage = parseInt(urlParams.get("page")) || 1;
  let totalCount = page_data.posts_count;
  const page_size = page_data.page_size;

  const paginationSection = document.querySelector(".pagination-section");
  if (!paginationSection) return;

  if (totalCount <= page_size) {
    paginationSection.style.display = "none";
    return;
  }

  paginationSection.style.display = "";
  const totalPages = Math.ceil(totalCount / page_size);

  // Setup Previous Button
  const prevBtn = document.getElementById("previous-btn");
  if (prevBtn) {
    if (currentPage === 1) {
      prevBtn.style.opacity = "0.5";
      prevBtn.style.pointerEvents = "none";
    } else {
      prevBtn.style.opacity = "1";
      prevBtn.style.pointerEvents = "auto";
      prevBtn.onclick = () => {
        urlParams.set("page", currentPage - 1);
        window.location.search = urlParams.toString();
      };
    }
  }

  // Setup Next Button
  const nextBtn = document.getElementById("next-btn");
  if (nextBtn) {
    if (currentPage >= totalPages) {
      nextBtn.style.opacity = "0.5";
      nextBtn.style.pointerEvents = "none";
    } else {
      nextBtn.style.opacity = "1";
      nextBtn.style.pointerEvents = "auto";
      nextBtn.onclick = () => {
        urlParams.set("page", currentPage + 1);
        window.location.search = urlParams.toString();
      };
    }
  }

  // Setup Page Numbers
  const numbersContainer = document.getElementById("pagination-container");
  if (numbersContainer) {
    numbersContainer.innerHTML = "";
    for (let i = 1; i <= totalPages; i++) {
      const pageEl = document.createElement("div");
      pageEl.className = "page-number";
      pageEl.style.cursor = "pointer";
      pageEl.style.color = "var(--ink-gray-5)";
      pageEl.style.fontSize = "13px";
      pageEl.style.padding = "4px 8px";
      pageEl.style.borderRadius = "8px";

      if (i === currentPage) {
        pageEl.style.color = "var(--ink-gray-7)";
        pageEl.style.fontWeight = "bold";
      }
      pageEl.innerHTML = `<p>${i}</p>`;
      pageEl.onclick = () => {
        if (i !== currentPage) {
          urlParams.set("page", i);
          window.location.search = urlParams.toString();
        }
      };
      numbersContainer.appendChild(pageEl);
    }
  }
});
